int main(int argc,char** argv){qputenv("QT_QPA_PLATFORM","windows");QApplication app(argc,argv);app.setStyleSheet(application_style_sheet());std::cout.setf(std::ios::unitbuf);try{std::cout<<"Native platform="<<QGuiApplication::platformName().toStdString()<<" PID="<<QCoreApplication::applicationPid()<<" actual product style/Qt Library action; physical/clipboard/fonts/geometry NOT_RUN\n";QTemporaryDir temp;check(temp.isValid(),"Owned scratch valid");const auto requested=qEnvironmentVariable("NECT_FOLDER_PLACEMENT_DOCUMENT_ROOT"),root=QDir::fromNativeSeparators(requested.isEmpty()?temp.path():requested);int failures=0;for(int mode=0;mode<11;++mode){try{flow(root,mode);std::cout<<"CASE PASS mode="<<mode<<"\n";}catch(const std::exception& e){++failures;std::cerr<<"CASE FAIL mode="<<mode<<" reason="<<e.what()<<" checks="<<checks<<"\n";}}if(failures)throw std::runtime_error("Folder placement document cases failed: "+std::to_string(failures));std::cout<<"PASS Folder placement document "<<checks<<" checks\n";return 0;}catch(const std::exception& e){std::cerr<<"FAIL Folder placement document "<<e.what()<<" after "<<checks<<" checks\n";return 1;}}
